{
  "findings": [
    {
      "check_id": "CKV_AWS_3",
      "title": "EBS volume encryption is disabled",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The volume explicitly sets encrypted = false, leaving all data stored on the EBS volume unencrypted at rest."
    },
    {
      "check_id": "CKV_AWS_189",
      "title": "EBS volume does not use a customer-managed KMS key",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The volume has no customer-managed KMS key configured, preventing fine-grained control over access to its encrypted data."
    }
  ],
  "patched_code": "resource \"aws_kms_key\" \"changeme_ebs_volume_key\" {\n  description         = \"Customer-managed key for EBS volume encryption\"\n  enable_key_rotation = true\n}\n\nresource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n  kms_key_id        = aws_kms_key.changeme_ebs_volume_key.arn\n}\n",
  "fix_summary": "Enabled encryption for the EBS volume and configured it to use a new customer-managed KMS key. Automatic KMS key rotation is enabled."
}
